    tmp=tempfile.mkdtemp(); env=dict(os.environ); env.update({"XDG_CONFIG_HOME":tmp+"/config","XDG_DATA_HOME":tmp+"/data","XDG_DATA_DIRS":tmp+"/data_dirs","HOME":tmp+"/home"})
    os.makedirs(tmp+"/config",exist_ok=True); os.makedirs(tmp+"/data",exist_ok=True)
