DEFAULT_CONFIG_TEXT = "enable_selector = false\nselector = \"rofi -dmenu -i -p 'Open With: '\"\n"

class TomlVal:
    __slots__ = ("value", "kind", "line", "col", "at", "raw")
    def __init__(self, value, kind, line, col, at, raw):
        self.value = value; self.kind = kind; self.line = line; self.col = col; self.at = at; self.raw = raw

class TomlError(Exception):
    def __init__(self, debug):
        self.debug = debug

def _toml_panic(debug):
    panic("src/config.rs:63:31", f"called `Result::unwrap()` on an `Err` value: BadTomlData({debug})")

def _toml_error(kind, line, col, at, message="", key=None):
    key_s = "[" + ", ".join(_rust_escape_str(k) for k in (key or [])) + "]"
    return (f'Error {{ inner: ErrorInner {{ kind: {kind}, line: Some({line}), col: {col}, '
            f'at: Some({at}), message: {_rust_escape_str(message)}, key: {key_s} }} }}')

class _TomlParser:
    def __init__(self, text):
        if text.startswith("\ufeff"):
            text = text[1:]
        self.s = text
        self.i = 0
        self.n = len(text)
        self.top = {}          # key -> TomlVal (top level only)
        self.top_counts = {}
        self.tables_seen = set()
        self.current_table = None  # None = top level

    def _line_col(self, at):
        line = self.s.count("\n", 0, at)
        last = self.s.rfind("\n", 0, at)
        col = at - (last + 1)
        return line, col

    def _err_unexpected(self, ch, at):
        line, col = self._line_col(at)
        raise TomlError(_toml_error(f"Unexpected({ _rust_escape_str(ch)[0] + chr(39) + ch + chr(39) + _rust_escape_str(ch)[-1] if False else repr(ch)})", line, col, at))

    def _fail(self, kind, at, key=None, message=""):
        line, col = self._line_col(at)
        raise TomlError(_toml_error(kind, line, col, at, message, key))

    def _skip_ws(self, newline=False):
        while self.i < self.n:
            c = self.s[self.i]
            if c in " \t":
                self.i += 1
            elif newline and c in "\r\n":
                self.i += 1
            elif newline and c == "#":
                while self.i < self.n and self.s[self.i] != "\n":
                    self.i += 1
            else:
                break

    def _peek(self):
        return self.s[self.i] if self.i < self.n else ""

    def parse(self):
        while True:
            self._skip_ws(newline=True)
            if self.i >= self.n:
                break
            if self._peek() == "[":
                self._parse_table_header()
            else:
                self._parse_keyval()
        return self.top

    def _parse_table_header(self):
        start = self.i
        line_start = self.s.rfind("\n", 0, start) + 1
        self.i += 1
        is_array = False
        if self._peek() == "[":
            is_array = True
            self.i += 1
        self._skip_ws()
        keys = self._parse_key()
        self._skip_ws()
        if self._peek() != "]":
            self._fail("Wanted { expected: \"a right bracket\", found: \"a newline\" }", self.i)
        self.i += 1
        if is_array:
            if self._peek() != "]":
                self._fail("Wanted { expected: \"a right bracket\", found: \"a newline\" }", self.i)
            self.i += 1
        name = ".".join(keys)
        if not is_array:
            if name in self.tables_seen:
                line, _ = self._line_col(line_start)
                raise TomlError(_toml_error(f'DuplicateTable("{name}")', line, 0, line_start, "", keys))
            self.tables_seen.add(name)
        self.current_table = name
        self._skip_ws()
        self._end_of_line()

    def _end_of_line(self):
        if self.i >= self.n:
            return
        c = self._peek()
        if c == "#":
            while self.i < self.n and self.s[self.i] != "\n":
                self.i += 1
            return
        if c == "\r":
            self.i += 1
            if self._peek() == "\n":
                return
            return
        if c == "\n":
            return
        line, col = self._line_col(self.i)
        raise TomlError(_toml_error(f"Unexpected('{c}')", line, col, self.i))

    def _parse_key(self):
        keys = []
        while True:
            self._skip_ws()
            c = self._peek()
            if c == '"' or c == "'":
                keys.append(self._parse_string())
            else:
                start = self.i
                while self.i < self.n and (self.s[self.i].isalnum() or self.s[self.i] in "_-"):
                    self.i += 1
                if self.i == start:
                    self._fail("Wanted { expected: \"an equals\", found: \"an identifier\" }", self.i)
                keys.append(self.s[start:self.i])
            self._skip_ws()
            if self._peek() == ".":
                self.i += 1
                continue
            break
        return keys

    def _parse_keyval(self):
        keys = self._parse_key()
        self._skip_ws()
        if self._peek() != "=":
            at = self.i
            found = "a newline" if (at >= self.n or self.s[at] in "\r\n") else "an identifier"
            self._fail(f'Wanted {{ expected: "an equals", found: "{found}" }}', at)
        self.i += 1
        self._skip_ws()
        val = self._parse_value()
        if self.current_table is None and len(keys) == 1:
            k = keys[0]
            self.top[k] = val
            self.top_counts[k] = self.top_counts.get(k, 0) + 1
        self._skip_ws()
        self._end_of_line()

    def _parse_string(self):
        # returns python str; handles basic/literal and multiline
        s = self.s; i = self.i
        quote = s[i]
        triple = s[i:i+3] == quote * 3
        if triple:
            self.i += 3
            if self._peek() == "\n":
                self.i += 1
            elif s[self.i:self.i+2] == "\r\n":
                self.i += 2
            out = []
            while self.i < self.n:
                if s[self.i:self.i+3] == quote * 3:
                    self.i += 3
                    return "".join(out)
                c = s[self.i]
                if quote == '"' and c == "\\":
                    # line-ending backslash or escape
                    j = self.i + 1
                    while j < self.n and s[j] in " \t":
                        j += 1
                    if s[j:j+1] == "\n" or s[j:j+2] == "\r\n":
                        self.i = j + (2 if s[j:j+2] == "\r\n" else 1)
                        while self.i < self.n and s[self.i] in " \t\r\n":
                            self.i += 1
                        continue
                    out.append(self._escape())
                    continue
                out.append(c)
                self.i += 1
            self._fail("UnquotedString", i)
        self.i += 1
        out = []
        while self.i < self.n:
            c = s[self.i]
            if c == quote:
                self.i += 1
                return "".join(out)
            if c == "\n":
                self._fail("UnquotedString", i)
            if quote == '"' and c == "\\":
                out.append(self._escape())
                continue
            out.append(c)
            self.i += 1
        self._fail("UnquotedString", i)

    def _escape(self):
        s = self.s
        at = self.i
        self.i += 1
        if self.i >= self.n:
            self._fail("UnquotedString", at)
        c = s[self.i]
        self.i += 1
        mp = {"b": "\b", "t": "\t", "n": "\n", "f": "\f", "r": "\r", '"': '"', "\\": "\\"}
        if c in mp:
            return mp[c]
        if c == "u":
            hx = s[self.i:self.i+4]; self.i += len(hx)
            try: return chr(int(hx, 16))
            except Exception: self._fail("UnquotedString", at)
        if c == "U":
            hx = s[self.i:self.i+8]; self.i += len(hx)
            try: return chr(int(hx, 16))
            except Exception: self._fail("UnquotedString", at)
        self._fail("UnquotedString", at)

    def _parse_value(self):
        s = self.s
        at = self.i
        line, col = self._line_col(at)
        c = self._peek()
        if c == '"' or c == "'":
            v = self._parse_string()
            return TomlVal(v, "string", line, col, at, v)
        if c == "[":
            self.i += 1
            items = []
            while True:
                self._skip_ws(newline=True)
                if self._peek() == "]":
                    self.i += 1; break
                if self.i >= self.n:
                    self._fail("UnquotedString", at)
                items.append(self._parse_value().value)
                self._skip_ws(newline=True)
                if self._peek() == ",":
                    self.i += 1; continue
                if self._peek() == "]":
                    self.i += 1; break
                self._fail("UnquotedString", self.i)
            return TomlVal(items, "sequence", line, col, at, "")
        if c == "{":
            self.i += 1
            d = {}
            while True:
                self._skip_ws()
                if self._peek() == "}":
                    self.i += 1; break
                keys = self._parse_key()
                self._skip_ws()
                if self._peek() != "=":
                    self._fail('Wanted { expected: "an equals", found: "an identifier" }', self.i)
                self.i += 1; self._skip_ws()
                d[".".join(keys)] = self._parse_value().value
                self._skip_ws()
                if self._peek() == ",":
                    self.i += 1; continue
                if self._peek() == "}":
                    self.i += 1; break
                self._fail("UnquotedString", self.i)
            return TomlVal(d, "map", line, col, at, "")
        # bare token up to newline/comment/comma/bracket
        start = self.i
        while self.i < self.n and s[self.i] not in "\r\n#,]}":
            self.i += 1
        raw = s[start:self.i].strip()
        if raw == "":
            self._fail("UnquotedString", at)
        if raw == "true" or raw == "false":
            return TomlVal(raw == "true", "boolean", line, col, at, raw)
        if re.fullmatch(r"[+-]?(\d[\d_]*|0x[0-9a-fA-F_]+|0o[0-7_]+|0b[01_]+)", raw):
            try:
                r = raw.replace("_", "")
                if r.lstrip("+-").startswith(("0x", "0X")):
                    v = int(r, 16)
                elif r.lstrip("+-").startswith(("0o", "0O")):
                    v = int(r, 8)
                elif r.lstrip("+-").startswith(("0b", "0B")):
                    v = int(r, 2)
                else:
                    v = int(r, 10)
            except Exception:
                v = 0
            return TomlVal(v, "integer", line, col, at, raw)
        if re.fullmatch(r"[+-]?(\d[\d_]*(\.[\d_]+)?([eE][+-]?\d+)?|inf|nan)", raw) and any(ch in raw for ch in ".eE") or raw.lstrip("+-") in ("inf", "nan"):
            try: v = float(raw.replace("_", ""))
            except Exception: v = 0.0
            return TomlVal(v, "float", line, col, at, raw)
        if re.match(r"\d{4}-\d{2}-\d{2}|\d{2}:\d{2}", raw):
            return TomlVal(raw, "datetime", line, col, at, raw)
        self._fail("UnquotedString", at)

class Config:
    def __init__(self, enable_selector=False, selector="rofi -dmenu -i -p 'Open With: '"):
        self.enable_selector = enable_selector
        self.selector = selector

CONFIG = None

def _config_type_panic(val, expected, key):
    if val.kind == "string":
        got = f"string {_rust_escape_str(val.value)}"
    elif val.kind == "integer":
        got = f"integer `{val.value}`"
    elif val.kind == "boolean":
        got = f"boolean `{str(val.value).lower()}`"
    elif val.kind == "float":
        got = f"float `{val.raw}`"
    elif val.kind == "sequence":
        got = "sequence"
        # toml crate reports sequence type errors at 0,0
        debug = _toml_error("Custom", 0, 0, 0, f"invalid type: {got}, expected {expected}", [key])
        _toml_panic(debug)
    elif val.kind == "map":
        got = "map"
        debug = _toml_error("Custom", 0, 0, 0, f"invalid type: {got}, expected {expected}", [key])
        _toml_panic(debug)
    else:
        got = val.kind
    debug = _toml_error("Custom", val.line, val.col, val.at, f"invalid type: {got}, expected {expected}", [key])
    _toml_panic(debug)

def load_config():
    global CONFIG
    path = config_file_path()
    if path is None:
        CONFIG = Config()
        return CONFIG
    parent = os.path.dirname(path)
    try:
        os.makedirs(parent, exist_ok=True)
    except OSError as e:
        panic("src/config.rs:63:31", f"called `Result::unwrap()` on an `Err` value: GeneralLoadError({os_error_debug(e.errno)})")
    if not os.path.exists(path):
        try:
            with open(path, "w", encoding="utf-8") as f:
                f.write(DEFAULT_CONFIG_TEXT)
        except OSError as e:
            panic("src/config.rs:63:31", f"called `Result::unwrap()` on an `Err` value: GeneralLoadError({os_error_debug(e.errno)})")
        CONFIG = Config()
        return CONFIG
    # exists: read
    try:
        with open(path, "rb") as f:
            raw = f.read()
    except IsADirectoryError as e:
        panic("src/config.rs:63:31", f"called `Result::unwrap()` on an `Err` value: ReadConfigurationFileError({os_error_debug(e.errno)})")
    except PermissionError as e:
        panic("src/config.rs:63:31", f"called `Result::unwrap()` on an `Err` value: GeneralLoadError({os_error_debug(e.errno)})")
    except OSError as e:
        panic("src/config.rs:63:31", f"called `Result::unwrap()` on an `Err` value: ReadConfigurationFileError({os_error_debug(e.errno)})")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        panic("src/config.rs:63:31", 'called `Result::unwrap()` on an `Err` value: ReadConfigurationFileError(Error { kind: InvalidData, message: "stream did not contain valid UTF-8" })')
    parser = _TomlParser(text)
    try:
        top = parser.parse()
    except TomlError as e:
        _toml_panic(e.debug)
    cfg = Config()
    for key, expected_kind, expected_txt in (("enable_selector", "boolean", "a boolean"), ("selector", "string", "a string")):
        if parser.top_counts.get(key, 0) > 1:
            debug = _toml_error("Custom", 0, 0, 0, f"duplicate field `{key}`", [])
            _toml_panic(debug)
        if key in top:
            val = top[key]
            if val.kind != expected_kind:
                _config_type_panic(val, expected_txt, key)
            setattr(cfg, key, val.value)
    CONFIG = cfg
    return cfg

# ----------------------------- Desktop entries -----------------------------

class DesktopEntry:
    __slots__ = ("handler_id", "path", "name", "exec_str", "terminal", "mime_types")
    def __init__(self, handler_id, path, name, exec_str, terminal, mime_types):
        self.handler_id = handler_id
        self.path = path
        self.name = name
        self.exec_str = exec_str
        self.terminal = terminal
        self.mime_types = mime_types

_desktop_cache = {}

def parse_desktop_file(path, handler_id):
    cache_key = path
    if cache_key in _desktop_cache:
        return _desktop_cache[cache_key]
    result = _parse_desktop_file_uncached(path, handler_id)
    _desktop_cache[cache_key] = result
    return result

def _parse_desktop_file_uncached(path, handler_id):
    try:
        with open(path, "rb") as f:
            raw = f.read()
    except Exception:
        return None
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        return None
    if text.startswith("\ufeff"):
        text = text[1:]
    lines = text.split("\n")
    # A trailing final newline produces a last empty element; that's a blank line, fine.
    sections = []  # list of [name, [(base, locale, value), ...]]
    current = None
    for line in lines:
        stripped_lead = line.lstrip(" \t")
        if stripped_lead.strip(" \t\r") == "":
            continue
        if stripped_lead.startswith("#"):
            continue
        if stripped_lead.startswith("["):
            close = stripped_lead.find("]")
            if close == -1:
                return None
            sec_name = stripped_lead[1:close]
            if sec_name == "":
                return None
            rest = stripped_lead[close+1:].lstrip(" \t")
            if rest not in ("", "\r") and not rest.startswith("#"):
                return None
            if rest.startswith("#"):
                pass
            current = [sec_name, []]
            sections.append(current)
            continue
        # attribute line
        if current is None:
            return None
        body = stripped_lead
        if "=" not in body:
            return None
        raw_name, value = body.split("=", 1)
        if raw_name == "":
            return None
        m = re.match(r"^([^\[]+)\[([^\]]*)\]$", raw_name)
        if m:
            base, locale = m.group(1), m.group(2)
        else:
            base, locale = raw_name, None
        current[1].append((base, locale, value))
    # last Desktop Entry section
    chosen = None
    for sec in sections:
        if sec[0] == "Desktop Entry":
            chosen = sec
    if chosen is None:
        return None
    def last_attr(base):
        v = None
        found = False
        for (b, loc, val) in chosen[1]:
            if b == base and loc is None:
                v = val; found = True
        return v if found else None
    name = last_attr("Name")
    exec_str = last_attr("Exec")
    if name is None or name == "" or exec_str is None or exec_str == "":
        return None
    terminal = last_attr("Terminal") == "true"
    mime_raw = last_attr("MimeType")
    mimes = []
    if mime_raw is not None:
        for frag in mime_raw.split(";"):
            if frag == "":
                continue
            try:
                mimes.append(parse_mime(frag))
            except Exception:
                continue
    return DesktopEntry(handler_id, path, name, exec_str, terminal, mimes)

def load_handler_by_id(handler_id):
    """Return DesktopEntry or raise ValueError with validator message."""
    for app_dir in application_dirs():
        candidate = os.path.join(app_dir, handler_id)
        # Rust Path::exists follows symlinks and is False on errors
        if os.path.exists(candidate):
            entry = parse_desktop_file(candidate, handler_id)
            if entry is None:
                raise ValueError(f"malformed desktop entry at {candidate}")
            return entry
    raise ValueError(f"no handlers found for '{handler_id}'")

def try_load_handler(handler_id):
    try:
        return load_handler_by_id(handler_id)
    except ValueError:
        return None

# ----------------------------- System applications -----------------------------

SYSTEM_APPS = {}  # Mime full -> list[DesktopEntry]

def load_system_apps():
    global SYSTEM_APPS
    apps = {}
    seen = set()
    for app_dir in application_dirs():
        try:
            entries = list(os.scandir(app_dir))
        except Exception:
            continue
        for de in entries:
            fname = de.name
            if fname in seen:
                continue
            seen.add(fname)
            if not fname.endswith(".desktop"):
                continue
            path = os.path.join(app_dir, fname)
            entry = parse_desktop_file(path, fname)
            if entry is None:
                continue
            for m in entry.mime_types:
                apps.setdefault(m.full, []).append(entry)
    SYSTEM_APPS = apps
    return apps

# ----------------------------- mimeapps.list -----------------------------

class MimeApps:
    def __init__(self):
        self.default = {}  # Mime -> list[DesktopEntry]
        self.added = {}
        self.path = mimeapps_path()

USER_APPS = None

def _pest_line_display(line):
    # pest renders the error line with a visible newline marker
    if line.endswith("\n"):
        return line[:-1] + "\u240a"
    return line

def _mimeapps_panic(content, char_pos, positives):
    byte_pos = len(content[:char_pos].encode("utf-8"))
    line_no = content.count("\n", 0, char_pos) + 1
    last_nl = content.rfind("\n", 0, char_pos)
    col = char_pos - last_nl
    # extract line containing char_pos (or last line at EOF)
    start = last_nl + 1
    end = content.find("\n", start)
    if end == -1:
        line = content[start:]
    else:
        line = content[start:end+1]
    pos_list = "[" + ", ".join(positives) + "]"
    debug = (f'ParseApps(Error {{ variant: ParsingError {{ positives: {pos_list}, negatives: [] }}, '
             f'location: Pos({byte_pos}), line_col: Pos(({line_no}, {col})), path: None, '
             f'line: {_rust_escape_str(_pest_line_display(line))}, continued_line: None }})')
    panic("src/apps/user.rs:12:65", f"called `Result::unwrap()` on an `Err` value: {debug}")

def _parse_mimeapps_content(content):
    if content.startswith("\ufeff"):
        _mimeapps_panic(content, 0, ["file"])
    sections = []  # (name, [(key,value)])
    current = None
    i = 0
    n = len(content)
    while i < n:
        ch = content[i]
        if ch == "\n":
            i += 1
            continue
        if ch == "\r" and i + 1 < n and content[i+1] == "\n":
            i += 2
            continue
        if ch == "\t":
            _mimeapps_panic(content, i, ["EOI", "name_char", "section", "comment"])
        if ch == "#":
            # comment to newline (required)
            j = i
            while j < n and content[j] != "\n":
                if content[j] == "\t":
                    _mimeapps_panic(content, j, ["name_char"])
                j += 1
            if j >= n:
                _mimeapps_panic(content, n, ["name_char"])
            i = j + 1
            continue
        if ch == "[":
            # section header
            close = -1
            j = i + 1
            while j < n and content[j] not in "]\n\t":
                j += 1
            if j < n and content[j] == "]":
                close = j
                sec_name = content[i+1:j]
                if sec_name == "":
                    _mimeapps_panic(content, j + 1, ["name_char"])
                # must be followed by \n or \r\n
                after = j + 1
                if after < n and content[after] == "\r" and after + 1 < n and content[after+1] == "\n":
                    current = [sec_name, []]
                    sections.append(current)
                    i = after + 2
                    continue
                if after < n and content[after] == "\n":
                    current = [sec_name, []]
                    sections.append(current)
                    i = after + 1
                    continue
                _mimeapps_panic(content, close, ["section_char"])
            else:
                _mimeapps_panic(content, j, ["section_char"])
        # attribute line
        line_start = i
        if ch == "=":
            _mimeapps_panic(content, i, ["EOI", "name_char", "section", "comment"])
        j = i
        while j < n and content[j] not in "=\n\t":
            if content[j] == "\r" and j + 1 < n and content[j+1] == "\n":
                break
            j += 1
        if j >= n or content[j] != "=":
            _mimeapps_panic(content, j, ["name_char"])
        key = content[line_start:j]
        j += 1
        vstart = j
        while j < n and content[j] != "\n":
            if content[j] == "\t":
                _mimeapps_panic(content, j, ["value_char"])
            if content[j] == "\r" and j + 1 < n and content[j+1] == "\n":
                break
            j += 1
        if j >= n:
            _mimeapps_panic(content, n, ["value_char"])
        value = content[vstart:j]
        if value == "":
            _mimeapps_panic(content, j, ["value_char"])
        if content[j] == "\r":
            j += 1  # the \r before \n
        # now at \n
        i = j + 1
        if current is None:
            current = ["", []]
            sections.append(current)
        current[1].append((key, value))
    return sections

def load_mimeapps():
    global USER_APPS
    apps = MimeApps()
    USER_APPS = apps
    path = apps.path
    if path is None:
        return apps
    # Open (create if missing) like OpenOptions read+write+create
    try:
        fd = os.open(path, os.O_RDWR | os.O_CREAT, 0o666)
    except OSError as e:
        panic("src/apps/user.rs:12:65", f"called `Result::unwrap()` on an `Err` value: Io({os_error_debug(e.errno)})")
    try:
        chunks = []
        while True:
            chunk = os.read(fd, 65536)
            if not chunk:
                break
            chunks.append(chunk)
        raw = b"".join(chunks)
    except OSError as e:
        panic("src/apps/user.rs:12:65", f"called `Result::unwrap()` on an `Err` value: Io({os_error_debug(e.errno)})")
    finally:
        os.close(fd)
    try:
        content = raw.decode("utf-8")
    except UnicodeDecodeError:
        panic("src/apps/user.rs:12:65", 'called `Result::unwrap()` on an `Err` value: Io(Error { kind: InvalidData, message: "stream did not contain valid UTF-8" })')
    sections = _parse_mimeapps_content(content)
    for sec_name, attrs in sections:
        if sec_name == "Default Applications":
            target = apps.default
        elif sec_name == "Added Associations":
            target = apps.added
        else:
            continue
        for (key, value) in attrs:
            # A key carrying mime parameters (other than a bare trailing ';')
            # is ignored when read back from the file.
            if ";" in key and key.split(";", 1)[1] != "":
                continue
            try:
                mime = parse_mime(key)
            except Exception:
                continue
            entries = []
            seen_ids = set()
            for frag in value.split(";"):
                if frag == "":
                    continue
                if frag in seen_ids:
                    continue
                entry = try_load_handler(frag)
                if entry is None:
                    continue
                seen_ids.add(frag)
                entries.append(entry)
            if entries:
                target[mime] = entries
    return apps

def write_mimeapps(apps):
    path = apps.path
    if path is None:
        raise IoMainError(2)
    def section_lines(mapping):
        lines = []
        for mime in sorted(mapping.keys(), key=lambda m: m.full):
            ids = ";".join(e.handler_id for e in mapping[mime])
            lines.append(f"{mime.essence}={ids};\n")
        return "".join(lines)
    text = "[Added Associations]\n" + section_lines(apps.added) + "\n[Default Applications]\n" + section_lines(apps.default)
    try:
        with open(path, "w", encoding="utf-8") as f:
            f.write(text)
    except OSError as e:
        raise io_from_oserror(e)

# ----------------------------- shell-like splitting (Rust shlex) -----------------------------

def shlex_split(s):
    tokens = []
    cur = []
    has_word = False
    state = "bare"  # bare | single | double
    i = 0
    n = len(s)
    def finish():
        nonlocal cur, has_word
        if has_word:
            tokens.append("".join(cur))
        cur = []
        has_word = False
    while i < n:
        c = s[i]
        if state == "bare":
            if c in " \t\n":
                finish()
                i += 1
                continue
            if c == "#" and not has_word and not cur:
                break
            if c == "\\":
                if i + 1 >= n:
                    return None
                cur.append(s[i+1]); has_word = True; i += 2; continue
            if c == "'":
                state = "single"; has_word = True; i += 1; continue
            if c == '"':
                state = "double"; has_word = True; i += 1; continue
            cur.append(c); has_word = True; i += 1; continue
        elif state == "single":
            if c == "'":
                state = "bare"; i += 1; continue
            cur.append(c); i += 1; continue
        else:  # double
            if c == '"':
                state = "bare"; i += 1; continue
            if c == "\\":
                if i + 1 >= n:
                    return None
                nxt = s[i+1]
                if nxt in ('"', "\\", "$", "`"):
                    cur.append(nxt)
                else:
                    cur.append("\\"); cur.append(nxt)
                i += 2; continue
            cur.append(c); i += 1; continue
    if state != "bare":
        return None
    finish()
    return tokens

# ----------------------------- command construction / launching -----------------------------

FIELD_CODES = ("%f", "%F", "%u", "%U")

def expand_exec(entry, args):
    raw = entry.exec_str
    split = shlex_split(raw)
    if split is None:
        panic("src/common/desktop_entry.rs:65:49", "called `Option::unwrap()` on a `None` value")
    has_code = any(code in raw for code in FIELD_CODES)
    if not has_code:
        return split + list(args)
    joined = " ".join(args)
    out = []
    for token in split:
        if token in FIELD_CODES:
            out.extend(args)
            continue
        # find earliest field code in token
        best_idx = None; best_code = None
        for code in FIELD_CODES:
            k = token.find(code)
            if k != -1 and (best_idx is None or k < best_idx):
                best_idx = k; best_code = code
        if best_code is not None:
            replaced = token[:best_idx] + joined + token[best_idx+2:]
            if replaced != "":
                out.append(replaced)
        else:
            out.append(token)
    return out

def build_command_tokens(entry, args):
    expanded = expand_exec(entry, args)
    if entry.terminal:
        term_mime = parse_mime("x-scheme-handler/terminal")
        term_entry = get_handler(term_mime)
        term_tokens = shlex_split(term_entry.exec_str)
        if term_tokens is None:
            panic("src/common/desktop_entry.rs:65:49", "called `Option::unwrap()` on a `None` value")
        return term_tokens + ["-e"] + expanded
    return expanded

def command_prog_args(entry, args):
    tokens = build_command_tokens(entry, args)
    if not tokens:
        panic("src/common/desktop_entry.rs:105:18", "removal index (is 0) should be < len (is 0)")
    return tokens[0], tokens[1:]

def entry_cmd_string(entry):
    prog, rest = command_prog_args(entry, [])
    return f"{prog} {' '.join(rest)}"

def spawn_prog(prog, rest):
    try:
        subprocess.Popen([prog] + rest, stdin=None, stdout=subprocess.DEVNULL,
                         stderr=subprocess.DEVNULL, close_fds=True)
    except (OSError, ValueError):
        raise IoMainError(2)

def launch_entry(entry, args):
    prog, rest = command_prog_args(entry, args)
    spawn_prog(prog, rest)

# ----------------------------- selector -----------------------------

def run_selector(names):
    tokens = shlex_split(CONFIG.selector)
    if tokens is None:
        panic("src/config.rs:77:58", "called `Option::unwrap()` on a `None` value")
    if not tokens:
        panic("src/config.rs:78:38", "removal index (is 0) should be < len (is 0)")
    prog, rest = tokens[0], tokens[1:]
    data = "\n".join(names).encode("utf-8", "surrogateescape")
    try:
        proc = subprocess.Popen([prog] + rest, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=None)
        out, _ = proc.communicate(data)
    except Exception:
        return ""
    try:
        return out.decode("utf-8")
    except Exception:
        return ""

# ----------------------------- handler resolution -----------------------------

def get_handler(mime):
    apps = USER_APPS
    entries = None
    if apps is not None:
        entries = apps.default.get(mime)
        if entries is None:
            entries = apps.default.get(wildcard_of(mime))
        if entries is not None:
            if CONFIG is not None and CONFIG.enable_selector and len(entries) > 1:
                names = [e.name for e in entries]
                selected = run_selector(names).rstrip() if False else None
                # Rust: output.trim_end(); empty -> first; else find by name (unwrap)
                out = run_selector_cache(names) if False else None
                # NOTE: run_selector called once below (placeholder removed)
                raise RuntimeError("unreachable")
            return entries[0]
    raise RuntimeError("unreachable")

