#!/usr/bin/env python3
import os
import sys

# Reimplementation of handlr 0.6.4 behaviour (written from observed CLI behaviour).

try:
    sys.stdout.reconfigure(errors="surrogateescape")
    sys.stderr.reconfigure(errors="surrogateescape")
except Exception:
    pass

import json
import re
import subprocess
import stat
import pwd
from urllib.parse import quote, unquote_to_bytes

VERSION = "0.6.4"

BIN = os.path.basename(sys.argv[0]) or "handlr"
# When invoked through a shebang the interpreter supplies the script path,
# whose basename is what clap would have used.
if BIN.endswith(".py"):
    BIN = "executable"

# ----------------------------- Rust-like errors / panics -----------------------------

ERRNO_KIND = {
    1: "PermissionDenied", 2: "NotFound", 3: "NotFound", 4: "Interrupted",
    5: "Other", 9: "Other", 11: "WouldBlock", 13: "PermissionDenied",
    17: "AlreadyExists", 20: "NotADirectory", 21: "IsADirectory",
    22: "InvalidInput", 24: "Other", 32: "BrokenPipe", 28: "StorageFull",
    30: "ReadOnlyFilesystem", 36: "InvalidFilename", 39: "DirectoryNotEmpty",
    40: "FilesystemLoop", 7: "InvalidInput", 14: "Other", 26: "Other",
}

def _rust_escape_str(s):
    out = []
    for ch in s:
        o = ord(ch)
        if ch == '"': out.append('\\"')
        elif ch == "\\": out.append("\\\\")
        elif ch == "\n": out.append("\\n")
        elif ch == "\r": out.append("\\r")
        elif ch == "\t": out.append("\\t")
        elif o < 0x20 or o == 0x7f:
            out.append("\\u{%x}" % o)
        else:
            out.append(ch)
    return '"' + "".join(out) + '"'

def os_error_debug(errno_value, message=None):
    if errno_value is None:
        errno_value = 2
    kind = ERRNO_KIND.get(errno_value, "Other")
    if message is None:
        try:
            message = os.strerror(errno_value)
        except Exception:
            message = "No such file or directory"
    return f'Os {{ code: {errno_value}, kind: {kind}, message: {_rust_escape_str(message)} }}'

class IoMainError(Exception):
    def __init__(self, errno_value=2, message=None, debug_override=None):
        self.errno_value = errno_value
        self.message = message
        self.debug_override = debug_override
    def debug(self):
        if self.debug_override is not None:
            return self.debug_override
        return os_error_debug(self.errno_value, self.message)

def io_from_oserror(e):
    return IoMainError(e.errno if getattr(e, "errno", None) else 2,
                        os.strerror(e.errno) if getattr(e, "errno", None) else str(e))

class PanicExit(Exception):
    def __init__(self, location, message):
        self.location = location
        self.message = message

def panic(location, message):
    raise PanicExit(location, message)

def emit_panic_and_exit(location, message):
    sys.stderr.write(f"\nthread 'main' ({os.getpid()}) panicked at {location}:\n{message}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    sys.stderr.flush()
    raise SystemExit(101)

# ----------------------------- XDG paths -----------------------------

def home_dir():
    h = os.environ.get("HOME")
    if h:
        return h
    try:
        return pwd.getpwuid(os.getuid()).pw_dir
    except Exception:
        return None

def _abs_env(name):
    v = os.environ.get(name)
    if v and os.path.isabs(v):
        return v
    return None

def config_home():
    v = _abs_env("XDG_CONFIG_HOME")
    if v is not None:
        return v
    h = home_dir()
    if h is None:
        return None
    return os.path.join(h, ".config")

def data_home():
    v = _abs_env("XDG_DATA_HOME")
    if v is not None:
        return v
    h = home_dir()
    if h is None:
        return None
    return os.path.join(h, ".local", "share")

def data_dirs():
    v = os.environ.get("XDG_DATA_DIRS")
    if v is None or v == "":
        return ["/usr/local/share", "/usr/share"]
    out = []
    for part in v.split(":"):
        if part and os.path.isabs(part):
            out.append(part)
    return out

def all_data_bases():
    out = []
    dh = data_home()
    if dh is not None:
        out.append(dh)
    out.extend(data_dirs())
    return out

def application_dirs():
    return [os.path.join(b, "applications") for b in all_data_bases()]

def config_file_path():
    ch = config_home()
    if ch is None:
        return None
    return os.path.join(ch, "handlr", "handlr.toml")

def mimeapps_path():
    ch = config_home()
    if ch is None:
        return None
    return os.path.join(ch, "mimeapps.list")

# ----------------------------- MIME parsing -----------------------------

TOKEN_CHARS = set(b"!#$%&'*+-.^_`|~")
def _is_token_byte(b):
    return (48 <= b <= 57) or (65 <= b <= 90) or (97 <= b <= 122) or b in TOKEN_CHARS

class Mime:
    __slots__ = ("typ", "sub", "params", "essence", "full")
    def __init__(self, typ, sub, params=()):
        self.typ = typ
        self.sub = sub
        self.params = tuple(params)
        self.essence = f"{typ}/{sub}"
        if self.params:
            parts = []
            for (k, v) in self.params:
                if v == "" or all(_is_token_byte(b) for b in v.encode("utf-8", "surrogateescape")):
                    parts.append(f"; {k}={v}")
                else:
                    esc = v.replace("\\", "\\\\").replace('"', '\\"')
                    parts.append(f'; {k}="{esc}"')
            self.full = self.essence + "".join(parts)
        else:
            self.full = self.essence
    def __eq__(self, other):
        return isinstance(other, Mime) and self.full == other.full
    def __hash__(self):
        return hash(self.full)
    def __repr__(self):
        return f"Mime({self.full!r})"

class MimeParseError(ValueError):
    pass

def _mime_err_invalid(byte, pos):
    return MimeParseError(f"mime parse error: an invalid token was encountered, {byte:X} at position {pos}")

def parse_mime(s):
    # Work on UTF-8 bytes to get Rust (mime crate) byte positions.
    b = s.encode("utf-8", "surrogateescape")
    n = len(b)
    pos = 0
    while pos < n and _is_token_byte(b[pos]):
        pos += 1
    if pos >= n:
        # whole string was a token (or empty)
        raise MimeParseError("mime parse error: a slash (/) was missing between the type and subtype")
    if pos == 0 or b[pos:pos+1] != b"/":
        raise _mime_err_invalid(b[pos], pos)
    typ = b[:pos].decode("ascii").lower()
    pos += 1
    if pos >= n:
        raise MimeParseError(f"bad mime: {s}")
    start = pos
    while pos < n and _is_token_byte(b[pos]):
        pos += 1
    if pos == start:
        raise _mime_err_invalid(b[pos], pos)
    sub = b[start:pos].decode("ascii").lower()
    params = []
    while pos < n:
        if b[pos:pos+1] != b";":
            raise _mime_err_invalid(b[pos], pos)
        pos += 1
        while pos < n and b[pos:pos+1] == b" ":
            pos += 1
        if pos >= n:
            break
        pstart = pos
        while pos < n and _is_token_byte(b[pos]):
            pos += 1
        if pos == pstart:
            raise _mime_err_invalid(b[pos], pos)
        pname = b[pstart:pos].decode("ascii").lower()
        if pos >= n:
            raise MimeParseError("mime parse error: an equals sign (=) was missing between a parameter and its value")
        if b[pos:pos+1] != b"=":
            if b[pos:pos+1] == b";":
                raise MimeParseError("mime parse error: an equals sign (=) was missing between a parameter and its value")
            raise _mime_err_invalid(b[pos], pos)
        pos += 1
        if pos < n and b[pos:pos+1] == b'"':
            pos += 1
            vstart = pos
            # find closing quote (backslash does not escape it in the mime crate)
            closing = b.find(b'"', pos)
            if closing == -1 or closing == vstart:
                raise MimeParseError('mime parse error: a quote (") was missing from a parameter value')
            pvalue = b[vstart:closing].decode("utf-8", "surrogateescape")
            pos = closing + 1
            while pos < n and b[pos:pos+1] == b" ":
                pos += 1
            params.append((pname, pvalue))
            if pos < n and b[pos:pos+1] != b";":
                raise _mime_err_invalid(b[pos], pos)
            continue
        vstart = pos
        while pos < n and _is_token_byte(b[pos]):
            pos += 1
        pvalue = b[vstart:pos].decode("utf-8", "surrogateescape")
        if pos < n and b[pos:pos+1] != b";":
            raise _mime_err_invalid(b[pos], pos)
        params.append((pname, pvalue))
    return Mime(typ, sub, params)

def wildcard_of(m):
    return Mime(m.typ, "*")

# ----------------------------- Shared mime database -----------------------------

def _translate_glob(pat):
    i = 0
    out = []
    n = len(pat)
    while i < n:
        c = pat[i]
        if c == "*":
            out.append(".*")
            i += 1
        elif c == "?":
            out.append(".")
            i += 1
        elif c == "[":
            j = i + 1
            if j < n and pat[j] in "!^":
                j += 1
            if j < n and pat[j] == "]":
                j += 1
            while j < n and pat[j] != "]":
                j += 1
            if j >= n:
                raise ValueError("bad glob")
            cls = pat[i+1:j]
            neg = False
            if cls.startswith("!"):
                neg = True
                cls = cls[1:]
            cls = cls.replace("\\", "\\\\")
            out.append("[" + ("^" if neg else "") + cls + "]")
            i = j + 1
        else:
            out.append(re.escape(c))
            i += 1
    return "".join(out)

class GlobEntry:
    __slots__ = ("weight", "mime", "pattern", "cs", "idx", "_re_cache")
    def __init__(self, weight, mime, pattern, cs, idx):
        self.weight = weight
        self.mime = mime
        self.pattern = pattern
        self.cs = cs
        self.idx = idx
        self._re_cache = {}
    def _sensitive(self):
        if self.cs:
            return True
        if not any(ch in self.pattern for ch in "*?["):
            # literal filename patterns match case-insensitively
            return False
        if any('A' <= ch <= 'Z' for ch in self.pattern):
            return True
        return False
    def matches(self, filename):
        sens = self._sensitive()
        key = sens
        rx = self._re_cache.get(key)
        if rx is None:
            pat = self.pattern if sens else self.pattern.lower()
            try:
                rx = re.compile("^" + _translate_glob(pat) + r"\Z", re.DOTALL)
            except Exception:
                rx = False
            self._re_cache[key] = rx
        if rx is False:
            return False
        name = filename if sens else filename.lower()
        return rx.match(name) is not None

class MagicMatch:
    __slots__ = ("offset", "value", "mask")
    def __init__(self, offset, value, mask):
        self.offset = offset
        self.value = value
        self.mask = mask
    def matches(self, data):
        off = self.offset
        v = self.value
        if off < 0 or off + len(v) > len(data):
            return False
        if self.mask is not None:
            for i in range(len(v)):
                m = self.mask[i] if i < len(self.mask) else 0
                if (data[off+i] & m) != (v[i] & m):
                    return False
            return True
        return data[off:off+len(v)] == v

class MagicEntry:
    __slots__ = ("priority", "mime", "matches")
    def __init__(self, priority, mime, matches):
        self.priority = priority
        self.mime = mime
        self.matches = matches

def _parse_magic_file(data):
    out = []
    header = b"MIME-Magic\x00\n"
    if not data.startswith(header):
        return out
    pos = len(header)
    n = len(data)
    while pos < n:
        if data[pos:pos+1] == b"\n":
            pos += 1
            continue
        line_end = data.find(b"\n", pos)
        if line_end == -1:
            break
        line = data[pos:line_end]
        if not (line.startswith(b"[") and line.endswith(b"]")):
            break
        inner = line[1:-1]
        if b":" not in inner:
            break
        prio_s, mime_s = inner.split(b":", 1)
        try:
            prio = int(prio_s.decode("ascii"))
            mime = parse_mime(mime_s.decode("utf-8"))
        except Exception:
            break
        pos = line_end + 1
        matches = []
        ok = True
        while pos < n and data[pos:pos+1] == b">":
            eq = data.find(b"=", pos)
            if eq == -1:
                ok = False; pos = n; break
            offset_raw = data[pos+1:eq]
            try:
                off_text = offset_raw.decode("ascii")
                offset = int(off_text, 10)
                if offset < 0:
                    offset = 0
            except Exception:
                offset = 0
            if eq + 3 > n:
                ok = False; pos = n; break
            vlen = int.from_bytes(data[eq+1:eq+3], "big")
            vstart = eq + 3
            vend = vstart + vlen
            if vend > n:
                ok = False; pos = n; break
            value = data[vstart:vend]
            p = vend
            mask = None
            if p < n and data[p:p+1] == b"&":
                p += 1
                mask = data[p:p+vlen]
                p += vlen
            # ignore any suffix (e.g. ~wordsize) until newline
            nl = data.find(b"\n", p)
            if nl == -1:
                ok = False; pos = n; break
            matches.append(MagicMatch(offset, value, mask))
            pos = nl + 1
        if ok and matches:
            out.append(MagicEntry(prio, mime, matches))
    return out

class MimeDb:
    _cache = None

    def __init__(self):
        self.globs = []
        self.magics = []
        self.aliases = {}
        self.subclasses = {}
        idx = 0
        for base in all_data_bases():
            mime_dir = os.path.join(base, "mime")
            # globs2 wins over globs if present (per directory)
            g2 = os.path.join(mime_dir, "globs2")
            g1 = os.path.join(mime_dir, "globs")
            if os.path.lexists(g2):
                idx = self._load_globs(g2, True, idx)
            elif os.path.lexists(g1):
                idx = self._load_globs(g1, False, idx)
            # aliases
            self._load_pairs(os.path.join(mime_dir, "aliases"), self.aliases)
            sub_tmp = {}
            self._load_pairs(os.path.join(mime_dir, "subclasses"), sub_tmp)
            for k, v in sub_tmp.items():
                self.subclasses.setdefault(k, []).append(v)
            # magic
            mpath = os.path.join(mime_dir, "magic")
            try:
                with open(mpath, "rb") as f:
                    self.magics.extend(_parse_magic_file(f.read()))
            except Exception:
                pass

    def _load_pairs(self, path, dest):
        try:
            with open(path, "rb") as f:
                raw = f.read()
            text = raw.decode("utf-8")
        except Exception:
            return
        for line in text.split("\n"):
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            parts = line.split()
            if len(parts) < 2:
                continue
            try:
                a = parse_mime(parts[0]); b = parse_mime(parts[1])
            except Exception:
                continue
            dest[a.full] = b

    def _load_globs(self, path, is_globs2, idx):
        try:
            with open(path, "rb") as f:
                raw = f.read()
            text = raw.decode("utf-8")
        except Exception:
            return idx
        for line in text.split("\n"):
            if line.endswith("\r"):
                line = line[:-1]
            if not line or line.startswith("#"):
                continue
            try:
                if is_globs2:
                    parts = line.split(":", 3)
                    if len(parts) < 3:
                        continue
                    weight = int(parts[0])
                    mime = parse_mime(parts[1])
                    pattern = parts[2]
                    cs = False
                    if len(parts) >= 4:
                        # flags field; pattern may itself contain ':' if the
                        # producer used more fields -- real files keep flags last.
                        # Only treat as flags if it looks like flags.
                        if parts[3] == "cs":
                            cs = True
                        else:
                            pattern = parts[2] + ":" + parts[3]
                else:
                    if ":" not in line:
                        continue
                    ms, pattern = line.split(":", 1)
                    weight = 50
                    mime = parse_mime(ms)
                    cs = False
            except Exception:
                continue
            if pattern == "":
                continue
            self.globs.append(GlobEntry(weight, mime, pattern, cs, idx))
            idx += 1
        return idx

    def _depth(self, mime, seen=None):
        if seen is None:
            seen = set()
        if mime.full in seen:
            return 0
        seen = seen | {mime.full}
        parents = self.subclasses.get(mime.full) or (
            [self.subclasses[mime.full]] if isinstance(self.subclasses.get(mime.full), Mime) else [])
        # subclasses stored as lists above except aliases-style loading rewrote: normalise
        plist = self._parents(mime.full)
        if not plist:
            return 0
        return 1 + max(self._depth(p, seen) for p in plist)

    def _parents(self, mime_full):
        v = self.subclasses.get(mime_full)
        if v is None:
            return []
        if isinstance(v, list):
            return v
        return [v]

    def mimes_for_filename(self, filename):
        if filename is None:
            return []
        matched = [g for g in self.globs if g.matches(filename)]
        # xdg-mime returns these in ascending weight order; subclass parents
        # sort before their children.
        matched.sort(key=lambda g: (g.weight, self._depth(g.mime), g.idx))
        return [g.mime for g in matched]

    @classmethod
    def get(cls):
        if cls._cache is None:
            cls._cache = MimeDb()
        return cls._cache

def parse_user_mime(s):
    if s.startswith("."):
        db = MimeDb.get()
        mimes = db.mimes_for_filename(s)
        if not mimes:
            raise ValueError(f"could not figure out the mime type of '{s}'")
        return mimes[0]
    try:
        return parse_mime(s)
    except MimeParseError as e:
        raise ValueError(str(e))

