SPECIAL_PORTS = {"ftp": 21, "http": 80, "https": 443, "ws": 80, "wss": 443}

def _pct_encode(s, encode_set_extra, encode_nonascii=True):
    out = []
    bs = s.encode("utf-8", "surrogateescape")
    for b in bs:
        ch = chr(b)
        if b < 0x20 or b == 0x7f or (encode_nonascii and b > 0x7e) or ch in encode_set_extra:
            out.append("%%%02X" % b)
        else:
            out.append(ch)
    return "".join(out)

PATH_ENCODE = ' "`<>{}'
QUERY_SPECIAL_ENCODE = " \"'<>#"
QUERY_ENCODE = ' "<>#'
FRAGMENT_ENCODE = " \"<>`"
USERINFO_ENCODE = ' "/:;=@[\\]^|`<>{}'

def _is_windows_drive_seg(seg):
    return len(seg) == 2 and seg[0].isalpha() and seg[1] in ":|"

def _normalize_dot_segments(raw_path):
    # raw_path begins with '/' for our callers (or may be '')
    if raw_path == "":
        return []
    parts = raw_path.split("/")
    # drop the empty piece before leading slash
    if parts and parts[0] == "":
        parts = parts[1:]
    out = []
    trailing = False
    for idx, seg in enumerate(parts):
        low = seg.lower()
        if low in ("..", "%2e%2e", ".%2e", "%2e."):
            if out:
                out.pop()
            trailing = True
        elif low in (".", "%2e"):
            trailing = True
        else:
            out.append(seg)
            trailing = (seg == "")
    return (out, trailing)

def _serialize_path_segments(segs, trailing, force_slash=True):
    enc = [_pct_encode(s, PATH_ENCODE) for s in segs]
    if not enc:
        return "/" if force_slash else ""
    p = "/" + "/".join(enc)
    if trailing and not p.endswith("/"):
        p += "/"
    return p

def _parse_ipv4(host):
    # returns serialized ipv4 string, "domain" sentinel, or None for failure
    parts = host.split(".")
    if parts and parts[-1] == "" and len(parts) > 1:
        parts = parts[:-1]
    if not parts or len(parts) > 4:
        return "domain"
    def num(p):
        if p == "":
            return 0
        try:
            if p[:2].lower() == "0x":
                return int(p[2:], 16) if p[2:] else 0
            if len(p) > 1 and p[0] == "0":
                return int(p, 8)
            if not p.isdigit():
                return None
            return int(p, 10)
        except Exception:
            return None
    nums = [num(p) for p in parts]
    if any(v is None for v in nums):
        return "domain"
    # Ends-in-a-number determination: last part numeric-ish
    last = parts[-1]
    if last == "" or num(last) is None:
        return "domain"
    for v in nums[:-1]:
        if v > 255:
            return None
    if nums[-1] >= 256 ** (5 - len(nums)):
        return None
    val = nums[-1]
    for i, v in enumerate(nums[:-1]):
        val += v * (256 ** (3 - i))
    return f"{(val >> 24) & 255}.{(val >> 16) & 255}.{(val >> 8) & 255}.{val & 255}"

def _parse_host(host_raw, special):
    # returns (serialized_host, is_empty) or None on failure
    if host_raw == "":
        return ("", True)
    if host_raw.startswith("["):
        return None  # handled by caller for IPv6
    # percent-decode
    try:
        decoded = unquote_to_bytes(host_raw).decode("utf-8")
    except Exception:
        decoded = unquote_to_bytes(host_raw).decode("utf-8", "replace")
    if special:
        ipv4 = _parse_ipv4(decoded)
        if ipv4 is None:
            return None
        if ipv4 != "domain":
            return (ipv4, False)
        host = decoded.lower()
        if any(ch in host for ch in "\x00\t\n\r %#/:<>?@[\\]^|"):
            return None
        labels = host.split(".")
        out_labels = []
        for lab in labels:
            if lab == "":
                out_labels.append("")
                continue
            if all(ord(c) < 128 for c in lab):
                out_labels.append(lab)
            else:
                try:
                    out_labels.append(lab.encode("idna").decode("ascii"))
                except Exception:
                    return None
        return (".".join(out_labels), False)
    else:
        # opaque host: reject forbidden, percent-encode C0/non-ascii etc.
        if any(ch in decoded for ch in "\x00\t\n\r#/:<>?@[\\]^|"):
            return None
        return (_pct_encode(decoded, ""), False)

