def _jaro(s1, s2):
    if s1 == s2:
        return 1.0
    l1, l2 = len(s1), len(s2)
    if l1 == 0 or l2 == 0:
        return 0.0
    md = max(l1, l2) // 2 - 1
    if md < 0:
        md = 0
    m1 = [False] * l1; m2 = [False] * l2
    matches = 0
    for i in range(l1):
        lo = max(0, i - md); hi = min(l2, i + md + 1)
        for j in range(lo, hi):
            if not m2[j] and s1[i] == s2[j]:
                m1[i] = m2[j] = True; matches += 1; break
    if matches == 0:
        return 0.0
    t = 0; k = 0
    for i in range(l1):
        if m1[i]:
            while not m2[k]:
                k += 1
            if s1[i] != s2[k]:
                t += 1
            k += 1
    t //= 2
    return (matches / l1 + matches / l2 + (matches - t) / matches) / 3

def _jaro_winkler(s1, s2):
    j = _jaro(s1, s2)
    prefix = 0
    for a, b in zip(s1, s2):
        if a == b and prefix < 4:
            prefix += 1
        else:
            break
    return j + prefix * 0.1 * (1 - j)

def _did_you_mean(value, candidates):
    best = None; best_v = 0.8
    for c in candidates:
        v = _jaro_winkler(value, c)
        if v > best_v:
            best_v = v; best = c
    return best

LONG_FLAGS = {
    None: ["help", "version"],
    "list": ["all", "help", "version"],
    "get": ["json", "help", "version"],
    "open": ["help", "version"], "set": ["help", "version"], "unset": ["help", "version"],
    "launch": ["help", "version"], "add": ["help", "version"],
}

class ArgParser:
    """Small emulation of clap 3.0.0-beta.2 behaviour for this application."""
    def __init__(self, argv):
        self.argv = argv
        self.invalid_utf8 = [self._was_invalid(a) for a in argv]

    @staticmethod
    def _was_invalid(a):
        bs = os.fsencode(a)
        try:
            bs.decode("utf-8")
            return False
        except Exception:
            return True

    def _lossy(self, a):
        return os.fsencode(a).decode("utf-8", "replace")

    def parse(self):
        args = [self._lossy(a) for a in self.argv]
        # top level scan for subcommand
        i = 0
        n = len(args)
        saw_dd = False
        while i < n:
            tok = args[i]
            if not saw_dd and tok == "--":
                saw_dd = True
                i += 1
                continue
            if not saw_dd and self._is_flag_token(tok):
                self._handle_flag_top(tok)
                i += 1
                continue
            if saw_dd:
                _unknown_arg(tok, None)
            if tok in SUBCOMMANDS:
                rest = args[i+1:]
                rest_invalid = self.invalid_utf8[i+1:]
                return tok, self._parse_sub(tok, rest, rest_invalid)
            # unknown word: maybe a suggested subcommand
            sugg = _did_you_mean(tok, SUBCOMMANDS) if tok and not tok.startswith("-") else None
            if sugg:
                _unknown_arg(tok, None, suggestion=sugg, subcommand_suggestion=True)
            _unknown_arg(tok, None)
        # no subcommand
        raise ClapExit(top_help(), 2, to_stderr=True)

    def _is_flag_token(self, tok):
        return len(tok) > 1 and tok[0] == "-" and tok != "-"

    def _long_name(self, tok):
        # clap trims all leading hyphens
        s = tok.lstrip("-")
        if "=" in s:
            s = s.split("=", 1)[0]
        return s

    def _handle_flag_top(self, tok):
        if tok.startswith("--"):
            name = self._long_name(tok)
            if name == "help":
                raise ClapExit(top_help(), 0, to_stderr=False)
            if name == "version":
                raise ClapExit("handlr 0.6.4\n", 0, to_stderr=False)
            display = "--" + name if name else "--"
            sugg = _did_you_mean(name, LONG_FLAGS[None]) if name else None
            _unknown_arg(display, None, suggestion=("--" + sugg) if sugg else None)
        else:
            # short cluster
            for ch in tok[1:]:
                if ch == "h":
                    raise ClapExit(top_help(), 0, to_stderr=False)
                if ch == "V":
                    raise ClapExit("handlr 0.6.4\n", 0, to_stderr=False)
                _unknown_arg("-" + ch, None)

    def _parse_sub(self, sub, args, invalid_flags):
        flags = {"all": 0, "json": 0}
        positionals = []
        pos_invalid = []
        saw_dd = False
        used_named_flag = False
        i = 0
        while i < len(args):
            tok = args[i]
            inv = invalid_flags[i]
            i += 1
            if not saw_dd and tok == "--":
                saw_dd = True
                continue
            if not saw_dd and self._is_flag_token(tok):
                if tok.startswith("--"):
                    name = self._long_name(tok)
                    if name == "help":
                        raise ClapExit(sub_help(sub), 0, to_stderr=False)
                    if name == "version":
                        raise ClapExit(sub_version(sub), 0, to_stderr=False)
                    if (sub == "list" and name == "all") or (sub == "get" and name == "json"):
                        flags[name] += 1
                        used_named_flag = True
                        continue
                    display = "--" + name if name else "--"
                    sugg = _did_you_mean(name, LONG_FLAGS[sub]) if name else None
                    usage = None
                    if sugg:
                        usage = self._smart_usage_suggestion(sub, sugg)
                    elif used_named_flag:
                        usage = self._smart_usage_used(sub, flags)
                    _unknown_arg(display, sub, usage=usage, suggestion=("--" + sugg) if sugg else None)
                else:
                    for ch in tok[1:]:
                        if ch == "h":
                            raise ClapExit(sub_help(sub), 0, to_stderr=False)
                        if ch == "V":
                            raise ClapExit(sub_version(sub), 0, to_stderr=False)
                        if sub == "list" and ch == "a":
                            flags["all"] += 1
                            used_named_flag = True
                            continue
                        usage = self._smart_usage_used(sub, flags) if used_named_flag else None
                        _unknown_arg("-" + ch, sub, usage=usage)
                continue
            # positional
            positionals.append(tok)
            pos_invalid.append(inv)
            # structural excess check happens immediately (before later --help)
            maxpos = {"list": 0, "get": 1, "unset": 1, "set": 2, "add": 2}.get(sub)
            if maxpos is not None and len(positionals) > maxpos:
                _unknown_arg(tok, sub)
        # empty positional values / missing / duplicates / validators
        self._post_validate(sub, flags, positionals, pos_invalid)
        return {"flags": flags, "positionals": positionals, "pos_invalid": pos_invalid}

    def _smart_usage_suggestion(self, sub, sugg_flag):
        if sub == "get":
            return f"{BIN} get <mime> --json"
        if sub == "list":
            return f"{BIN} list --all"
        return usage_of(sub)

    def _smart_usage_used(self, sub, flags):
        if sub == "list" and flags.get("all"):
            return f"{BIN} list --all"
        if sub == "get" and flags.get("json"):
            return f"{BIN} get <mime> --json"
        if sub == "launch":
            return f"{BIN} launch <mime> <args>..."
        return usage_of(sub)

    def _missing(self, sub, missing, flags=None):
        usage = usage_of(sub)
        if sub == "get" and flags and flags.get("json"):
            usage = f"{BIN} get <mime> --json"
        body = "The following required arguments were not provided:\n" + "\n".join(f"    {m}" for m in missing) + "\n"
        raise ClapExit(_err_text(body, usage), 2)

    def _empty_value(self, sub, arg_name):
        usage = usage_of(sub)
        if sub == "launch" and arg_name == "<args>...":
            usage = f"{BIN} launch <mime> [args]..."
        body = f"The argument '{arg_name}' requires a value but none was supplied\n"
        raise ClapExit(_err_text(body, usage), 2)

    def _invalid_value(self, arg_name, message):
        text = (f"error: Invalid value for '{arg_name}': {message}\n\nFor more information try --help\n")
        raise ClapExit(text, 2)

    def _post_validate(self, sub, flags, positionals, pos_invalid):
        # required counts
        if sub == "open":
            if len(positionals) < 1:
                self._missing(sub, ["<paths>..."], flags)
        elif sub == "set" or sub == "add":
            miss = []
            if len(positionals) < 1: miss.append("<mime>")
            if len(positionals) < 2: miss.append("<handler>")
            if miss: self._missing(sub, miss, flags)
        elif sub == "unset":
            if len(positionals) < 1: self._missing(sub, ["<mime>"], flags)
        elif sub == "get":
            if len(positionals) < 1: self._missing(sub, ["<mime>"], flags)
        elif sub == "launch":
            if len(positionals) < 1: self._missing(sub, ["<mime>"], flags)
        # empty values
        names = {
            "open": ["<paths>..."],
            "get": ["<mime>"], "unset": ["<mime>"],
            "set": ["<mime>", "<handler>"], "add": ["<mime>", "<handler>"],
            "launch": None, "list": [],
        }
        if sub == "launch":
            if positionals and positionals[0] == "":
                self._empty_value(sub, "<mime>")
            for p in positionals[1:]:
                if p == "":
                    self._empty_value(sub, "<args>...")
        elif sub in names:
            for idx, p in enumerate(positionals):
                if p == "":
                    nm = names[sub][idx] if idx < len(names[sub]) else names[sub][-1]
                    self._empty_value(sub, nm)
        # duplicate flags
        for fname in ("all", "json"):
            if flags.get(fname, 0) > 1:
                body = f"The argument '--{fname}' was provided more than once, but cannot be used multiple times\n"
                raise ClapExit(_err_text(body, usage_of(sub)), 2)
        # invalid UTF-8 in open paths / launch args panics in clap when read back
        if sub == "open" and any(pos_invalid):
            panic("/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/clap-3.0.0-beta.2/src/parse/matches/arg_matches.rs:220:28", "unexpected invalid UTF-8 code point")
        if sub == "launch" and len(pos_invalid) > 1 and any(pos_invalid[1:]):
            panic("/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/clap-3.0.0-beta.2/src/parse/matches/arg_matches.rs:220:28", "unexpected invalid UTF-8 code point")
        # validators (converted values are stored back into positionals via caller dict)
        # We validate here and stash converted objects on self.
        self.converted = {}
        if sub in ("get", "unset"):
            try:
                self.converted["mime"] = parse_user_mime(positionals[0])
            except ValueError as e:
                self._invalid_value("<mime>", str(e))
        elif sub in ("set", "add"):
            try:
                self.converted["mime"] = parse_user_mime(positionals[0])
            except ValueError as e:
                self._invalid_value("<mime>", str(e))
            try:
                self.converted["handler_entry"] = load_handler_by_id(positionals[1])
            except ValueError as e:
                self._invalid_value("<handler>", str(e))
        elif sub == "launch":
            try:
                self.converted["mime"] = parse_user_mime(positionals[0])
            except ValueError as e:
                self._invalid_value("<mime>", str(e))
        elif sub == "open":
            conv = []
            for p in positionals:
                try:
                    conv.append(parse_path_or_url(p))
                except ValueError as e:
                    self._invalid_value("<paths>...", str(e))
            self.converted["paths"] = conv

# ----------------------------- commands -----------------------------

def cmd_list(show_all):
    if not show_all:
        sys.stdout.write(render_table(_rows_of(USER_APPS.default)))
        return 0
    out = []
    out.append("Default Apps\n" + render_table(_rows_of(USER_APPS.default)))
    if USER_APPS.added:
        out.append("Added Associations\n" + render_table(_rows_of(USER_APPS.added)))
    # system rows
    sys_map = {}
    for mfull, entries in SYSTEM_APPS.items():
        try:
            m = parse_mime(mfull)
        except Exception:
            continue
        sys_map[m] = entries
    out.append("System Apps\n" + render_table(_rows_of(sys_map)))
    sys.stdout.write("".join(out))
    return 0

def cmd_get(mime, as_json):
    entry = get_handler(mime)
    if as_json:
        cmd = entry_cmd_string(entry)
        obj = {"handler": entry.handler_id, "name": entry.name, "cmd": cmd}
        sys.stdout.write(json.dumps(obj, ensure_ascii=False, separators=(",", ":")) + "\n")
    else:
        sys.stdout.write(entry.handler_id + "\n")
    return 0

def cmd_set(mime, handler_entry, add=False):
    if add:
        USER_APPS.default.setdefault(mime, []).append(handler_entry)
    else:
        USER_APPS.default[mime] = [handler_entry]
    write_mimeapps(USER_APPS)
    return 0

def cmd_unset(mime):
    if mime in USER_APPS.default:
        del USER_APPS.default[mime]
        write_mimeapps(USER_APPS)
    return 0

def cmd_launch(mime, args):
    entry = get_handler(mime)
    launch_entry(entry, args)
    return 0

def cmd_open(paths):
    resolved = []
    for pou in paths:
        mime = mime_for_path_or_url(pou)
        entry = get_handler(mime)
        resolved.append((entry, pou.value))
    # group by handler identity, preserving first-appearance order
    groups = []
    index = {}
    for entry, value in resolved:
        key = id(entry)
        # entries from caches are shared; a handler chosen from user apps and
        # system could be distinct objects for the same file -- normalise by path.
        key = entry.path
        if key not in index:
            index[key] = len(groups)
            groups.append((entry, []))
        groups[index[key]][1].append(value)
    for entry, values in groups:
        raw = entry.exec_str
        if "%F" in raw or "%U" in raw:
            launch_entry(entry, values)
        else:
            for v in values:
                launch_entry(entry, [v])
    return 0

# ----------------------------- main -----------------------------

def main(argv):
    # Eager startup (before CLI parsing, like the reference):
    load_config()
    load_mimeapps()
    load_system_apps()
    parser = ArgParser(argv)
    try:
        sub, parsed = parser.parse()
    except ClapExit as e:
        (sys.stderr if e.to_stderr else sys.stdout).write(e.text)
        return e.code
    conv = parser.converted
    flags = parsed["flags"]
    pos = parsed["positionals"]
    if sub == "list":
        return cmd_list(flags.get("all", 0) > 0)
    if sub == "get":
        return cmd_get(conv["mime"], flags.get("json", 0) > 0)
    if sub == "set":
        return cmd_set(conv["mime"], conv["handler_entry"], add=False)
    if sub == "add":
        return cmd_set(conv["mime"], conv["handler_entry"], add=True)
    if sub == "unset":
        return cmd_unset(conv["mime"])
    if sub == "launch":
        return cmd_launch(conv["mime"], pos[1:])
    if sub == "open":
        return cmd_open(conv["paths"])
    return 0

if __name__ == "__main__":
    try:
        code = main(sys.argv[1:])
    except PanicExit as p:
        emit_panic_and_exit(p.location, p.message)
    except IoMainError as e:
        sys.stderr.write(f"Error: Io({e.debug()})\n")
        code = 1
    except BrokenPipeError:
        try:
            sys.stderr.write("\nthread 'main' panicked at 'failed printing to stdout: Broken pipe (os error 32)'\n")
        except Exception:
            pass
        code = 101
    sys.exit(code)
