def sub_help(sub):
    head = f"{BIN}-{sub} \n{DESCRIPTIONS[sub]}\n\n"
    if sub == "list":
        return head + f"USAGE:\n    {BIN} list [FLAGS]\n\nFLAGS:\n    -a, --all        \n    -h, --help       Prints help information\n    -V, --version    Prints version information\n"
    if sub == "open":
        return head + f"USAGE:\n    {BIN} open <paths>...\n\nARGS:\n    <paths>...    \n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n"
    if sub == "set":
        return head + f"USAGE:\n    {BIN} set <mime> <handler>\n\nARGS:\n    <mime>       \n    <handler>    \n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n"
    if sub == "unset":
        return head + f"USAGE:\n    {BIN} unset <mime>\n\nARGS:\n    <mime>    \n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n"
    if sub == "launch":
        return head + f"USAGE:\n    {BIN} launch <mime> [args]...\n\nARGS:\n    <mime>       \n    <args>...    \n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n"
    if sub == "get":
        return head + f"USAGE:\n    {BIN} get [FLAGS] <mime>\n\nARGS:\n    <mime>    \n\nFLAGS:\n        --json       \n    -h, --help       Prints help information\n    -V, --version    Prints version information\n"
    if sub == "add":
        return head + f"USAGE:\n    {BIN} add <mime> <handler>\n\nARGS:\n    <mime>       \n    <handler>    \n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n"
    return head

def sub_version(sub):
    return f"{BIN}-{sub} \n"

def usage_of(sub):
    if sub is None:
        return f"{BIN} <SUBCOMMAND>"
    return {
        "list": f"{BIN} list [FLAGS]",
        "open": f"{BIN} open <paths>...",
        "set": f"{BIN} set <mime> <handler>",
        "unset": f"{BIN} unset <mime>",
        "launch": f"{BIN} launch <mime> [args]...",
        "get": f"{BIN} get [FLAGS] <mime>",
        "add": f"{BIN} add <mime> <handler>",
    }[sub]

class ClapExit(Exception):
    def __init__(self, text, code, to_stderr=True):
        self.text = text; self.code = code; self.to_stderr = to_stderr

def _err_text(body, usage):
    return f"error: {body}\n\nUSAGE:\n    {usage}\n\nFor more information try --help\n"

def _unknown_arg(arg_display, sub, usage=None, suggestion=None, subcommand_suggestion=False, original=None):
    usage = usage or usage_of(sub)
    if subcommand_suggestion and suggestion:
        body = (f"The subcommand '{arg_display}' wasn't recognized\n\n\tDid you mean '{suggestion}'?\n\n"
                f"If you believe you received this message in error, try re-running with '{BIN} -- {arg_display}'\n")
        raise ClapExit(_err_text(body, usage), 2)
    parts = [f"Found argument '{arg_display}' which wasn't expected, or isn't valid in this context\n"]
    if suggestion:
        parts.append(f"\n\tDid you mean '{suggestion}'?\n")
    parts.append(f"\nIf you tried to supply `{arg_display}` as a PATTERN use `-- {arg_display}`\n")
    raise ClapExit(_err_text("".join(parts), usage), 2)

def _jaro(s1, s2):
    if s1 == s2:
        return 1.0
    l1, l2 = len(s1), len(s2)
    if l1 == 0 or l2 == 0:
        return 0.0
    md = max(l1, l2) // 2 - 1
    if md < 0:
        md = 0
    m1 = [False] * l1; m2 = [False] * l2
    matches = 0
    for i in range(l1):
        lo = max(0, i - md); hi = min(l2, i + md + 1)
        for j in range(lo, hi):
            if not m2[j] and s1[i] == s2[j]:
                m1[i] = m2[j] = True; matches += 1; break
    if matches == 0:
        return 0.0
    t = 0; k = 0
    for i in range(l1):
        if m1[i]:
            while not m2[k]:
                k += 1
            if s1[i] != s2[k]:
                t += 1
            k += 1
    t //= 2
    return (matches / l1 + matches / l2 + (matches - t) / matches) / 3

def _jaro_winkler(s1, s2):
    j = _jaro(s1, s2)
    prefix = 0
    for a, b in zip(s1, s2):
        if a == b and prefix < 4:
            prefix += 1
        else:
            break
    return j + prefix * 0.1 * (1 - j)

def _did_you_mean(value, candidates):
    best = None; best_v = 0.8
    for c in candidates:
        v = _jaro_winkler(value, c)
        if v > best_v:
            best_v = v; best = c
    return best

LONG_FLAGS = {
    None: ["help", "version"],
    "list": ["all", "help", "version"],
    "get": ["json", "help", "version"],
    "open": ["help", "version"], "set": ["help", "version"], "unset": ["help", "version"],
    "launch": ["help", "version"], "add": ["help", "version"],
}

class ArgParser:
    """Small emulation of clap 3.0.0-beta.2 behaviour for this application."""
    def __init__(self, argv):
        self.argv = argv
        self.invalid_utf8 = [self._was_invalid(a) for a in argv]

    @staticmethod
    def _was_invalid(a):
        bs = os.fsencode(a)
        try:
            bs.decode("utf-8")
            return False
        except Exception:
            return True

    def _lossy(self, a):
        return os.fsencode(a).decode("utf-8", "replace")

    def parse(self):
        args = [self._lossy(a) for a in self.argv]
        # top level scan for subcommand
        i = 0
        n = len(args)
        saw_dd = False
        while i < n:
            tok = args[i]
            if not saw_dd and tok == "--":
                saw_dd = True
                i += 1
                continue
            if not saw_dd and self._is_flag_token(tok):
                self._handle_flag_top(tok)
                i += 1
                continue
            if saw_dd:
                _unknown_arg(tok, None)
            if tok in SUBCOMMANDS:
                rest = args[i+1:]
                rest_invalid = self.invalid_utf8[i+1:]
                return tok, self._parse_sub(tok, rest, rest_invalid)
            # unknown word: maybe a suggested subcommand
            sugg = _did_you_mean(tok, SUBCOMMANDS) if tok and not tok.startswith("-") else None
            if sugg:
                _unknown_arg(tok, None, suggestion=sugg, subcommand_suggestion=True)
            _unknown_arg(tok, None)
        # no subcommand
        raise ClapExit(top_help(), 2, to_stderr=True)

    def _is_flag_token(self, tok):
        return len(tok) > 1 and tok[0] == "-" and tok != "-"

    def _long_name(self, tok):
        # clap trims all leading hyphens
        s = tok.lstrip("-")
        if "=" in s:
            s = s.split("=", 1)[0]
        return s

    def _handle_flag_top(self, tok):
        if tok.startswith("--"):
            name = self._long_name(tok)
            if name == "help":
                raise ClapExit(top_help(), 0, to_stderr=False)
            if name == "version":
                raise ClapExit("handlr 0.6.4\n", 0, to_stderr=False)
            display = "--" + name if name else "--"
            sugg = _did_you_mean(name, LONG_FLAGS[None]) if name else None
            _unknown_arg(display, None, suggestion=("--" + sugg) if sugg else None)
        else:
