def cmd_list(show_all):
    if not show_all:
        sys.stdout.write(render_table(_rows_of(USER_APPS.default)))
        return 0
    out = []
    out.append("Default Apps\n" + render_table(_rows_of(USER_APPS.default)))
    if USER_APPS.added:
        out.append("Added Associations\n" + render_table(_rows_of(USER_APPS.added)))
    # system rows
    sys_map = {}
    for mfull, entries in SYSTEM_APPS.items():
        try:
            m = parse_mime(mfull)
        except Exception:
            continue
        sys_map[m] = entries
    out.append("System Apps\n" + render_table(_rows_of(sys_map)))
    sys.stdout.write("".join(out))
    return 0

def cmd_get(mime, as_json):
    entry = get_handler(mime)
    if as_json:
        cmd = entry_cmd_string(entry)
        obj = {"handler": entry.handler_id, "name": entry.name, "cmd": cmd}
        sys.stdout.write(json.dumps(obj, ensure_ascii=False, separators=(",", ":")) + "\n")
    else:
        sys.stdout.write(entry.handler_id + "\n")
    return 0

def cmd_set(mime, handler_entry, add=False):
    if add:
        USER_APPS.default.setdefault(mime, []).append(handler_entry)
    else:
        USER_APPS.default[mime] = [handler_entry]
    write_mimeapps(USER_APPS)
    return 0

def cmd_unset(mime):
    if mime in USER_APPS.default:
        del USER_APPS.default[mime]
        write_mimeapps(USER_APPS)
    return 0

def cmd_launch(mime, args):
    entry = get_handler(mime)
    launch_entry(entry, args)
    return 0

def cmd_open(paths):
    resolved = []
    for pou in paths:
        mime = mime_for_path_or_url(pou)
        entry = get_handler(mime)
        resolved.append((entry, pou.value))
    # group by handler identity, preserving first-appearance order
    groups = []
    index = {}
    for entry, value in resolved:
        key = id(entry)
        # entries from caches are shared; a handler chosen from user apps and
        # system could be distinct objects for the same file -- normalise by path.
        key = entry.path
        if key not in index:
            index[key] = len(groups)
            groups.append((entry, []))
        groups[index[key]][1].append(value)
    for entry, values in groups:
        raw = entry.exec_str
        if "%F" in raw or "%U" in raw:
            launch_entry(entry, values)
        else:
            for v in values:
                launch_entry(entry, [v])
    return 0

# ----------------------------- main -----------------------------

def main(argv):
    # Eager startup (before CLI parsing, like the reference):
    load_config()
    load_mimeapps()
    load_system_apps()
    parser = ArgParser(argv)
    try:
        sub, parsed = parser.parse()
    except ClapExit as e:
        (sys.stderr if e.to_stderr else sys.stdout).write(e.text)
        return e.code
    conv = parser.converted
    flags = parsed["flags"]
    pos = parsed["positionals"]
    if sub == "list":
        return cmd_list(flags.get("all", 0) > 0)
    if sub == "get":
        return cmd_get(conv["mime"], flags.get("json", 0) > 0)
    if sub == "set":
        return cmd_set(conv["mime"], conv["handler_entry"], add=False)
    if sub == "add":
        return cmd_set(conv["mime"], conv["handler_entry"], add=True)
    if sub == "unset":
        return cmd_unset(conv["mime"])
    if sub == "launch":
        return cmd_launch(conv["mime"], pos[1:])
    if sub == "open":
        return cmd_open(conv["paths"])
    return 0

