# ----------------------------- table rendering -----------------------------

def render_table(rows):
    # rows: list[(str,str)]
    if not rows:
        return "┌──┐\n│  │\n└──┘\n"
    w1 = max(len(r[0]) for r in rows)
    w2 = max(len(r[1]) for r in rows)
    out = []
    out.append("┌" + "─" * (w1 + 2) + "┬" + "─" * (w2 + 2) + "┐")
    for a, b in rows:
        out.append("│ " + a + " " * (w1 - len(a) + 1) + "│ " + b + " " * (w2 - len(b) + 1) + "│")
    out.append("└" + "─" * (w1 + 2) + "┴" + "─" * (w2 + 2) + "┘")
    return "\n".join(out) + "\n"

def _rows_of(mapping):
    rows = []
    for mime in sorted(mapping.keys(), key=lambda m: m.full):
        rows.append((mime.essence, ", ".join(e.handler_id for e in mapping[mime])))
    return rows

